// ─── File: ReflectionDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.reflectsealed;

import java.math.BigDecimal;
import java.util.logging.*;

public class ReflectionDemo {
    private static final Logger log = Logger.getLogger(ReflectionDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SealedScanner scanner = new SealedScanner();

        log.info(() -> "Account isSealed? " + Account.class.isSealed());

        // Direct permitted subtypes only (one level).
        StringBuilder direct = new StringBuilder();
        for (Class<?> c : Account.class.getPermittedSubclasses()) direct.append(c.getSimpleName()).append(" ");
        log.info(() -> "Direct permitted subtypes of Account: " + direct.toString().trim());

        // Full recursive discovery down to final leaves / non-sealed stops.
        log.info(() -> "Full discoverable set:");
        scanner.scan(Account.class, 0);

        // A non-sealed class returns null for getPermittedSubclasses and is NOT sealed.
        log.info(() -> "PartnerProduct isSealed? " + PartnerProduct.class.isSealed()
                + " (non-sealed → open, cannot enumerate its subclasses)");
    }
}

// ─── Would be in scan/SealedScanner.java ───
class SealedScanner {
    private static final Logger log = Logger.getLogger(SealedScanner.class.getName());

    // Recurse: if a permitted subtype is itself sealed, descend into it.
    void scan(Class<?> type, int depth) {
        String indent = "  ".repeat(depth);
        if (type.isSealed()) {
            log.info(() -> indent + type.getSimpleName() + " [sealed]");
            for (Class<?> sub : type.getPermittedSubclasses()) {
                scan(sub, depth + 1);                      // descend
            }
        } else if (java.lang.reflect.Modifier.isFinal(type.getModifiers())) {
            log.info(() -> indent + type.getSimpleName() + " [final leaf]");
        } else {
            // non-sealed: discovery stops — its subclasses are open/unknown.
            log.info(() -> indent + type.getSimpleName() + " [non-sealed → OPEN, cannot enumerate]");
        }
    }
}

// ─── Would be in model/Account.java ───
sealed interface Account permits SavingsAccount, LoanAccount, PartnerProduct {
    String id(); BigDecimal balance();
}
final class SavingsAccount implements Account {
    private final String id; private final BigDecimal balance;
        SavingsAccount(String id, BigDecimal balance) { this.id = id;
        this.balance = balance; }
    public String id() { return id; } public BigDecimal balance() { return balance; }
}
// Multi-level: LoanAccount is itself sealed.
sealed interface LoanAccount extends Account permits HomeLoan, CarLoan { }
final class HomeLoan implements LoanAccount {
    private final String id; private final BigDecimal balance;
        HomeLoan(String id, BigDecimal balance) { this.id = id;
        this.balance = balance; }
    public String id() { return id; } public BigDecimal balance() { return balance; }
}
final class CarLoan implements LoanAccount {
    private final String id; private final BigDecimal balance;
        CarLoan(String id, BigDecimal balance) { this.id = id;
        this.balance = balance; }
    public String id() { return id; } public BigDecimal balance() { return balance; }
}
// Open branch: discovery stops here.
non-sealed class PartnerProduct implements Account {
    private final String id; private final BigDecimal balance;
        PartnerProduct(String id, BigDecimal balance) { this.id = id;
        this.balance = balance; }
    public String id() { return id; } public BigDecimal balance() { return balance; }
}

